<?php
declare(strict_types=1);require_once __DIR__.'/../config/koneksi.php';require_once __DIR__.'/../vendor/autoload.php';use EnglAI\Auth\AccountService;use EnglAI\Security\Csrf;
if(session_status()!==PHP_SESSION_ACTIVE)session_start();$role=($_GET['role']??$_POST['role']??'student')==='teacher'?'teacher':'student';$code=strtoupper(trim((string)($_GET['classroom_code']??$_POST['classroom_code']??$_SESSION['pending_classroom_code']??'')));$error='';
if($role==='teacher'){header('Location: /admin/login.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){Csrf::requireValid($_POST['csrf_token']??null);$password=(string)($_POST['password']??'');if(!hash_equals($password,(string)($_POST['password_confirmation']??'')))$error='Konfirmasi password tidak cocok.';else try{$id=(new AccountService(db()))->register($role,(string)$_POST['email'],(string)$_POST['name'],$password);$q=db()->prepare('SELECT * FROM users WHERE id=?');$q->execute([$id]);AccountService::establish($q->fetch());header('Location: '.($role==='teacher'?'/admin/':($code!==''?'/student/continue.php?code='.rawurlencode($code):'/student/account.php')));exit;}catch(Throwable $e){$error=$e->getMessage();}}
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Register <?=ucfirst($role)?> · EnglAI</title><link rel="stylesheet" href="/assets/css/mvp.css"></head><body><div class="stars"></div><header class="nav"><a class="brand" href="/">EnglAI</a><a class="button secondary" href="/">← Home</a></header><main class="game-shell"><section class="card"><span class="eyebrow">Permanent Account</span><h1>Register <?=ucfirst($role)?></h1><?php if($error):?><div class="alert error"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></div><?php endif;?><form method="post"><?=Csrf::field()?><input type="hidden" name="role" value="<?=$role?>"><input type="hidden" name="classroom_code" value="<?=htmlspecialchars($code,ENT_QUOTES,'UTF-8')?>"><label>Name<input name="name" minlength="2" maxlength="120" required></label><label>Email<input type="email" name="email" maxlength="190" required></label><label>Password<input type="password" name="password" minlength="10" autocomplete="new-password" required></label><small class="muted">Minimal 10 karakter, huruf besar, huruf kecil, dan angka.</small><label>Confirm Password<input type="password" name="password_confirmation" minlength="10" required></label><button class="button primary wide">Create Account</button></form></section></main></body></html>
